package com.aoo.bcg.gamespi;

import java.util.Objects;

/**
 * Build/release-owned provider of the immutable runtime metadata projection.
 * Implementations may be generated by a release packager or backed by a
 * class-path resource; they must not read a developer checkout at runtime.
 */
@FunctionalInterface
public interface RuntimeMetadataProjectionSource {
    RuntimeMetadataProjection load();

    /** Readable alias for callers that model the source as a projection. */
    default RuntimeMetadataProjection projection() {
        return Objects.requireNonNull(load(), "runtime metadata projection");
    }

    static RuntimeMetadataProjectionSource of(RuntimeMetadataProjection projection) {
        Objects.requireNonNull(projection, "projection");
        return () -> projection;
    }
}
